# Surah Hud (chapter 11) — part 8: ayat 71-80 (IDs 1544-1553)
SURAH = 11

ENTRIES = {
1544: (
"اور — ان — کی بیوی — کھڑی — تھی — پس — وہ ہنسی — پس — ہم — نے — اس — کو — اسحاق — کی — اور اسحاق — کے بعد — یعقوب — کی خوشخبری — دی",
"""۱۔ ابراہیمؑ کی بیوی — کے لیے — اسحاق اور پھر یعقوبؑ — کی بشارت۔
۲۔ ’’وَامْرَأَتُهُ قَائِمَۃٌ فَضَحِكَتْ فَبَشَّرْنَاهَا بِإِسْحَاقَ وَمِن وَرَاءِ إِسْحَاقَ يَعْقُوبَ‘‘ — اور — ان — کی بیوی — کھڑی — تھی — پس — وہ ہنسی — پس — ہم — نے — اس — کو — اسحاق — کی — اور اسحاق — کے بعد — یعقوب — کی خوشخبری — دی — یعنی ابراہیمؑ کی بیوی — کھڑی — تھی — وہ — ہنسی — پس ہم نے — اس — کو — اسحاق — کی — اور اسحاق کے بعد یعقوبؑ — کی — خوشخبری — دی۔
۳۔ عملی سبق: اللہ کی بشارت — ناامید — ہو کر بھی مل سکتی ہے۔"""
),
1545: (
"انہوں نے کہا — اے — میرا افسوس — کیا — میں — جنے گی — اور — میں — بوڑھی عورت — ہوں — اور — یہ — میرے خاوند — ہیں — بوڑھا — یہ — تو — ایک — عجیب — چیز — ہے",
"""۱۔ سارہؑ — تعجب کا اظہار — عورت بوڑھی، خاوند بوڑھا۔
۲۔ ’’قَالَتْ يَا وَيْلَتَىٰ أَأَلِدُ وَأَنَا عَجُوزٌ وَهَٰذَا بَعْلِي شَيْخًا إِنَّ هَٰذَا لَشَيْءٌ عَجِيبٌ‘‘ — انہوں نے کہا — اے — میرا افسوس — کیا — میں — جنے گی — اور — میں — بوڑھی عورت — ہوں — اور — یہ — میرے خاوند — ہیں — بوڑھا — یہ — تو — ایک — عجیب — چیز — ہے — یعنی انہوں نے کہا — اے — میرا افسوس — کیا میں جنے گی — اور میں — بوڑھی عورت ہوں — اور یہ — میرے خاوند — بوڑھا — ہیں — یہ تو — ایک عجیب چیز — ہے۔
۳۔ عملی سبق: اللہ کی قدرت — سے — کوئی — چیز — بھی بعید — نہیں۔"""
),
1546: (
"انہوں نے — کہا — کیا — تم — اللہ کے امر — پر — تعجب کرتی ہو — اللہ کی رحمت اور اس کی برکتیں — تم پر ہیں — اے گھر والو — بے شک — وہ — بہت — تعریف کیا ہوا — بزرگی والا — ہے",
"""۱۔ فرشتوں نے کہا — اللہ کے امر پر تعجب مت کرو — اے اہلِ بیت۔
۲۔ ’’قَالُوا أَتَعْجَبِينَ مِنْ أَمْرِ اللَّهِ رَحْمَتُ اللَّهِ وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ إِنَّهُ حَمِيدٌ مَّجِيدٌ‘‘ — انہوں نے — کہا — کیا — تم — اللہ کے امر — پر — تعجب کرتی ہو — اللہ کی رحمت اور اس کی برکتیں — تم پر ہیں — اے گھر والو — بے شک — وہ — بہت — تعریف کیا ہوا — بزرگی والا — ہے — یعنی انہوں نے کہا — کیا تم اللہ کے امر پر — تعجب — کرتی ہو — اللہ کی رحمت اور برکتیں — تم پر ہوں — اے گھر والو (اہلِ بیت)؛ بے شک وہ — بڑے لائق تعریف — بزرگی والا — ہے — یہ آیت — اہلِ بیت (ع) کی — بے پناہ — کرامت — کی — شاہد ہے — اور — اسی — لفظ — نے — بعد — میں — رسولؐ — کے اہلِ بیت (ع) کو — عظیم مقام — بخشا۔
۳۔ عملی سبق: اہلِ بیتؑ — اللہ کی رحمت اور برکت کے حامل ہیں؛ محبت — اور احترام — رکھیں۔"""
),
1547: (
"پس — جب — ابراہیمؑ — سے — خوف — دور ہوا — اور — خوشخبری — ان تک پہنچ گئی — تو — وہ — ہمارے ساتھ — لوط — کی قوم — کے بارے میں — بحث کرنے لگے",
"""۱۔ ابراہیمؑ — خوشخبری کے بعد — لوط کی قوم کے بارے میں بحث۔
۲۔ ’’فَلَمَّا ذَهَبَ عَنْ إِبْرَاهِيمَ الرَّوْعُ وَجَاءَتْهُ الْبُشْرَىٰ يُجَادِلُنَا فِي قَوْمِ لُوطٍ‘‘ — پس — جب — ابراہیمؑ — سے — خوف — دور ہوا — اور — خوشخبری — ان تک پہنچ گئی — تو — وہ — ہمارے ساتھ — لوط — کی قوم — کے بارے میں — بحث کرنے لگے — یعنی جب ابراہیمؑ — سے خوف دور ہوا — اور خوشخبری پہنچی — تو وہ ہمارے ساتھ — لوطؑ کی قوم — کے بارے میں — بحث کرنے لگے۔
۳۔ عملی سبق: نبیوں کی — شفقت — علی العباد — بے پناہ — ہوتی ہے۔"""
),
1548: (
"بے شک — ابراہیمؑ — بہت مہربان — گھر والوں کے لیے — تڑپنے والا — بار بار — رجوع کرنے والا — تھا",
"""۱۔ ابراہیمؑ — حلیم، اواہ، منیب — ہیں۔
۲۔ ’’إِنَّ إِبْرَاهِيمَ لَحَلِيمٌ أَوَّاهٌ مُّنِيبٌ‘‘ — بے شک — ابراہیمؑ — بہت مہربان — گھر والوں کے لیے — تڑپنے والا — بار بار — رجوع کرنے والا — تھا — یعنی بے شک — ابراہیمؑ — بہت حلیم — اواہ (تڑپنے والے) — منیب (اللہ کی طرف بار بار لوٹنے والے) — تھے۔
۳۔ عملی سبق: حلیم، اواہ اور منیب — کے اوصاف — اپناؤ۔"""
),
1549: (
"اے — ابراہیمؑ — اس سے — پرہیز کرو — بے شک — تمہارے رب کا — حکم — آ چکا — اور — بے شک — ان — پر — ایسا عذاب — آنے والا ہے — جو — واپس — نہیں ہٹایا — جائے گا",
"""۱۔ بحث — بند کرو؛ اللہ کا حکم — آ چکا ہے۔
۲۔ ’’يَا إِبْرَاهِيمُ أَعْرِضْ عَنْ هَٰذَا إِنَّهُ قَدْ جَاءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ آتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ‘‘ — اے — ابراہیمؑ — اس سے — پرہیز کرو — بے شک — تمہارے رب کا — حکم — آ چکا — اور — بے شک — ان — پر — ایسا عذاب — آنے والا ہے — جو — واپس — نہیں ہٹایا — جائے گا — یعنی اے ابراہیمؑ — اس سے — پرہیز کرو — تمہارے رب کا حکم — آ چکا ہے — اور ان — پر — ایسا — عذاب — آنے والا ہے — جو واپس — نہیں — ہٹایا جائے گا۔
۳۔ عملی سبق: اللہ کا فیصلہ — حتمی — ہوتا ہے؛ تسلیم — کرو۔"""
),
1550: (
"اور — جب — ہمارے — بھیجے ہوئے — لوطؑ — کی طرف — آئے — تو — وہ — ان — سے — تنگ ہوا — اور — ان — لیے — بہت تنگ — ہوا — اور — کہا — یہ — ایک — سخت — دن — ہے",
"""۱۔ لوطؑ — فرشتوں کے آنے پر — تنگ اور پریشان — ہوئے۔
۲۔ ’’وَلَمَّا جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌ‘‘ — اور — جب — ہمارے — بھیجے ہوئے — لوطؑ — کی طرف — آئے — تو — وہ — ان — سے — تنگ ہوا — اور — ان — لیے — بہت تنگ — ہوا — اور — کہا — یہ — ایک — سخت — دن — ہے — یعنی جب ہمارے فرشتے — لوطؑ — کے پاس آئے — تو وہ ان — سے — پریشان — ہوا — اور ان کی وجہ سے — بہت — تنگ ہوا — اور کہا — یہ — ایک — سخت — دن — ہے۔
۳۔ عملی سبق: نبیؑ — بھی — مصائب میں — پریشان — ہو سکتے ہیں۔"""
),
1551: (
"اور — اس کی قوم — اس کے پاس — دوڑتے ہوئے — آئی — اور — اس — سے پہلے بھی — وہ — برائی — کرتے تھے — انہوں نے کہا — اے — میری قوم — یہ — میری — بیٹیاں — ہیں — وہ — تمہارے لیے — زیادہ پاک — ہیں — پس — اللہ سے ڈرو — اور — میرے — مہمانوں — کے بارے میں — مجھے — شرمندہ — نہ کرو — کیا — تم میں — کوئی — بھی — عقلمند آدمی — نہیں",
"""۱۔ لوطؑ — قوم کی غلط — سوچ کا — مقابلہ — کرتے ہیں۔
۲۔ ’’وَجَاءَهُ قَوْمُهُ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا يَعْمَلُونَ السَّيِّئَاتِ قَالَ يَا قَوْمِ هَٰؤُلَاءِ بَنَاتِي هُنَّ أَطْهَرُ لَكُمْ فَاتَّقُوا اللَّهَ وَلَا تُخْزُونِ فِي ضَيْفِي أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ‘‘ — اور — اس کی قوم — اس کے پاس — دوڑتے ہوئے — آئی — اور — اس — سے پہلے بھی — وہ — برائی — کرتے تھے — انہوں نے کہا — اے — میری قوم — یہ — میری — بیٹیاں — ہیں — وہ — تمہارے لیے — زیادہ پاک — ہیں — پس — اللہ سے ڈرو — اور — میرے — مہمانوں — کے بارے میں — مجھے — شرمندہ — نہ کرو — کیا — تم میں — کوئی — بھی — عقلمند آدمی — نہیں — یعنی اس کی قوم اس کے پاس — دوڑی آئی — وہ — پہلے بھی برائیاں کرتے تھے — لوطؑ نے کہا — اے میری قوم — یہ میری بیٹیاں ہیں — وہ تمہارے لیے زیادہ پاک ہیں — اللہ سے ڈرو — اور میرے مہمانوں — کے بارے میں مجھے شرمندہ — نہ کرو — کیا تم میں کوئی بھی عقلمند — آدمی نہیں۔
۳۔ عملی سبق: معاشرہ کی برائی — کے مقابلے میں — حکمت سے — بھاگنا — اور — نیکی — کی طرف بلایا جاتا ہے۔"""
),
1552: (
"انہوں نے کہا — تمہیں — معلوم ہے — ہمیں — تمہاری بیٹیوں میں کوئی حصہ — نہیں — اور — بے شک — تم — جانتے ہو — ہم — کیا — چاہتے ہیں",
"""۱۔ قوم — لوطؑ — اپنی بد — ارادوں — کو — نہیں چھپاتی۔
۲۔ ’’قَالُوا لَقَدْ عَلِمْتَ مَا لَنَا فِي بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ‘‘ — انہوں نے کہا — تمہیں — معلوم ہے — ہمیں — تمہاری بیٹیوں میں کوئی حصہ — نہیں — اور — بے شک — تم — جانتے ہو — ہم — کیا — چاہتے ہیں — یعنی انہوں نے کہا — آپ کو — معلوم ہے — ہمیں آپ کی بیٹیوں میں کوئی — حصہ نہیں — اور آپ — اچھی طرح — جانتے ہیں — ہم — کیا چاہتے ہیں۔
۳۔ عملی سبق: عقل کا فقدان — برائی کو — بے باکی — سے — کر دیتا ہے۔"""
),
1553: (
"انہوں نے — کہا — کاش — مجھ میں — تمہارے مقابلے کی — طاقت ہوتی — یا — میں — کسی — مضبوط — پناہ — کی طرف — پناہ لے سکتا",
"""۱۔ لوطؑ — قوم کی برائی کا مقابلہ کرنے کی — آرزو۔
۲۔ ’’قَالَ لَوْ أَنَّ لِي بِكُمْ قُوَّۃً أَوْ آوِي إِلَىٰ رُكْنٍ شَدِيدٍ‘‘ — انہوں نے — کہا — کاش — مجھ میں — تمہارے مقابلے کی — طاقت ہوتی — یا — میں — کسی — مضبوط — پناہ — کی طرف — پناہ لے سکتا — یعنی لوطؑ — نے کہا — کاش میرے پاس تمہارے مقابلے کی طاقت — ہوتی — یا — میں — کسی مضبوط پناہ — میں — پناہ — لے سکتا۔
۳۔ عملی سبق: حق — تنہا — ہو — تو بھی — بہادری — سے — کھڑا — رہو۔"""
),
}
